--
-- Table structure for table `wp_posts`
--

DROP TABLE IF EXISTS `wp_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_posts` (
  `ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `post_author` bigint unsigned NOT NULL DEFAULT '0',
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_title` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_excerpt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `post_password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `post_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `to_ping` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `pinged` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_parent` bigint unsigned NOT NULL DEFAULT '0',
  `guid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `menu_order` int NOT NULL DEFAULT '0',
  `post_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `comment_count` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`ID`),
  KEY `post_name` (`post_name`(191)),
  KEY `type_status_date` (`post_type`,`post_status`,`post_date`,`ID`),
  KEY `post_parent` (`post_parent`),
  KEY `post_author` (`post_author`),
  KEY `type_status_author` (`post_type`,`post_status`,`post_author`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wp_posts`
--

LOCK TABLES `wp_posts` WRITE;
/*!40000 ALTER TABLE `wp_posts` DISABLE KEYS */;
INSERT INTO `wp_posts` VALUES (1,1,'2021-10-15 08:00:00','2021-10-15 01:00:00','<p class=\"fit-lead\">Khoa Công nghệ Thông tin thông báo kế hoạch thực tập doanh nghiệp và đăng ký đồ án tốt nghiệp dành cho toàn thể sinh viên năm cuối khóa học 2021 – 2024.</p>\n\n<p>Thực tập tốt nghiệp là học phần bắt buộc nhằm giúp sinh viên cọ xát với môi trường làm việc thực tế tại các công ty công nghệ, doanh nghiệp phát triển phần mềm và các tổ chức quản trị mạng viễn thông. Sinh viên cần chủ động tìm kiếm đơn vị tiếp nhận thực tập hoặc lựa chọn theo danh sách các doanh nghiệp đối tác do khoa bảo trợ.</p>\n\n<p>Trong quá trình thực tập kéo dài 12 tuần, sinh viên phải thực hiện nghiêm túc nội quy cơ quan, ghi nhật ký công việc định kỳ và báo cáo tiến độ với giảng viên hướng dẫn. Sau khi hoàn thành thực tập, sinh viên sẽ bắt tay vào thực hiện đồ án tốt nghiệp với các đề tài mang tính ứng dụng thực tiễn cao như Xây dựng hệ thống Cloud, Ứng dụng AI, Phát triển ứng dụng Web/Mobile và An ninh mạng.</p>\n\n<p>Thời hạn nộp phiếu đăng ký nguyện vọng và đề cương đồ án tốt nghiệp về văn phòng khoa là trước ngày 30/11. Mọi thắc mắc sinh viên liên hệ trực tiếp văn phòng khoa hoặc cố vấn học tập để được hỗ trợ kịp thời.</p>\n\n<p class=\"fit-source\">(Nguồn: Ban Đào tạo Khoa Công nghệ Thông tin – TDC)</p>','Kế hoạch thực tập tốt nghiệp và đồ án chuyên ngành CNTT','','publish','open','open','','ke-hoach-thuc-tap-tot-nghiep-va-do-an-chuyen-nganh-cntt','','','2021-10-15 08:00:00','2021-10-15 01:00:00','',0,'http://wordpress.local/?p=1',0,'post','',1),(2,1,'2026-09-16 01:26:15','2026-09-16 01:26:15','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://wordpress.local/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','publish','closed','open','','sample-page','','','2026-09-16 01:26:15','2026-09-16 01:26:15','',0,'http://wordpress.local/?page_id=2',0,'page','',0),(3,1,'2026-09-16 01:26:15','2026-09-16 01:26:15','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://wordpress.local.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n','Privacy Policy','','draft','closed','open','','privacy-policy','','','2026-09-16 01:26:15','2026-09-16 01:26:15','',0,'http://wordpress.local/?page_id=3',0,'page','',0),(4,0,'2026-09-16 01:27:38','2026-09-16 01:27:38','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2026-09-16 01:27:38','2026-09-16 01:27:38','',0,'http://wordpress.local/?p=4',0,'wp_navigation','',0),(5,1,'2026-09-16 01:32:31','0000-00-00 00:00:00','','Auto Draft','','auto-draft','open','open','','','','','2026-09-16 01:32:31','0000-00-00 00:00:00','',0,'http://wordpress.local/?p=5',0,'post','',0),(6,0,'2021-10-08 09:30:00','2021-10-08 09:30:00','<p class=\"fit-lead\">Bộ môn Công nghệ Phần mềm - Khoa Công nghệ Thông tin tổ chức buổi Livestream Workshop với chủ đề \"From VS Code to Azure DevOps: Modern Software Development Practices\" dành cho toàn thể sinh viên.</p>\n\n<p>Hãy đăng ký tham gia buổi livestream workshop Bộ Môn Công Nghệ Phần Mềm vào lúc 9:30 ngày 16/10/2021 tại fanpage chính thức của Khoa Công Nghệ Thông Tin. Chương trình có sự tham gia chia sẻ của các chuyên gia đầu ngành trong lĩnh vực DevOps và kỹ sư phần mềm cao cấp đến từ các tập đoàn công nghệ hàng đầu.</p>\n\n<p>Tại buổi workshop, các bạn sinh viên sẽ được hướng dẫn thực hành quy trình CI/CD hiện đại, quản lý mã nguồn với Git, tự động hóa quy trình kiểm thử và triển khai ứng dụng lên đám mây Azure một cách chuyên nghiệp.</p>\n\n<p>Ban tổ chức sẽ dành tặng nhiều phần quà giá trị cùng chứng nhận tham gia cho các bạn sinh viên đặt câu hỏi hay và tương tác tích cực nhất trong buổi livestream.</p>\n\n<p class=\"fit-source\">(Nguồn: Bộ môn Công nghệ Phần mềm - TDC)</p>','ĐĂNG KÝ THAM GIA LIVESTREAM WORKSHOP BỘ MÔN CÔNG NGHỆ PHẦN MỀM','','publish','open','open','','dang-ky-tham-gia-livestream-workshop-bo-mon-cong-nghe-phan-mem','','','2021-10-08 09:30:00','2021-10-08 09:30:00','',0,'http://wordpress.local/?p=6',0,'post','',0),(7,0,'2021-10-07 14:00:00','2021-10-07 14:00:00','<p class=\"fit-lead\">Khoa Công nghệ Thông tin thông báo lịch phỏng vấn chính thức dành cho các sinh viên đăng ký tham gia chương trình đào tạo và làm việc tại Nhật Bản năm 2021.</p>\n\n<p>Các sinh viên có tên trong danh sách vui lòng có mặt theo đúng lịch trình và thời gian quy định tại phòng A112B để tham dự phỏng vấn cùng đại diện tập đoàn Freezia Group và Trường Cao đẳng Công nghệ Tokyo. Buổi phỏng vấn nhằm đánh giá năng lực tiếng Nhật cũng như kiến thức chuyên môn nền tảng về công nghệ thông tin của ứng viên.</p>\n\n<p>Khi tham dự, sinh viên cần chuẩn bị đầy đủ hồ sơ bao gồm: sơ yếu lý lịch (CV tiếng Nhật/Việt), bảng điểm học tập tính đến học kỳ gần nhất và các chứng chỉ liên quan (nếu có). Trang phục lịch sự, tác phong nghiêm túc theo chuẩn phong cách doanh nghiệp Nhật Bản.</p>\n\n<p>Đây là cơ hội tuyệt vời để các bạn sinh viên FIT-TDC tiếp cận môi trường làm việc quốc tế chuyên nghiệp và mở rộng tương lai nghề nghiệp sau khi tốt nghiệp.</p>\n\n<p class=\"fit-source\">(Nguồn: Khoa Công nghệ Thông tin - TDC)</p>','LỊCH PHỎNG VẤN CHƯƠNG TRÌNH CNTT NHẬT BẢN 2021','','publish','open','open','','lich-phong-van-chuong-trinh-cntt-nhat-ban-2021','','','2021-10-07 14:00:00','2021-10-07 14:00:00','',0,'http://wordpress.local/?p=7',0,'post','',0),(8,0,'2026-09-17 15:15:01','2026-09-17 15:15:01','','workshop-azure-devops','','inherit','open','closed','','workshop-azure-devops','','','2026-09-17 15:15:01','2026-09-17 15:15:01','',6,'http://wordpress.local/wp-content/uploads/2021/10/workshop-azure-devops.png',0,'attachment','image/png',0),(9,0,'2026-09-17 15:15:02','2026-09-17 15:15:02','','tuyen-sinh-cntt-japan','','inherit','open','closed','','tuyen-sinh-cntt-japan','','','2026-09-17 15:15:02','2026-09-17 15:15:02','',7,'http://wordpress.local/wp-content/uploads/2021/10/tuyen-sinh-cntt-japan.png',0,'attachment','image/png',0),(10,1,'2018-06-24 08:30:00','2018-06-24 01:30:00','<p class=\"fit-lead\">Theo khảo sát của VietnamWorks về ngành công nghệ thông tin (CNTT) ở Việt Nam, trong 3 năm qua, số lượng công việc ngành CNTT đã tăng trung bình 47%/năm.</p>\n\n<p>Tuy nhiên, số lượng nhân sự ngành này lại chỉ tăng ở mức trung bình 8% dẫn đến việc thiếu hụt nghiêm trọng nhân lực trong lĩnh vực này. Nguyên nhân chính được đưa ra là do số lượng doanh nghiệp tuyển dụng trong ngành CNTT đã tăng 69% từ năm 2012. Đặc biệt, số lượng công ty phần mềm đã tăng đến 124% chỉ trong vòng 4 năm. Khảo sát cũng cho thấy nếu cứ tiếp tục tăng trưởng nhân lực CNTT ở mức 8% như hiện nay, Việt Nam sẽ thiếu hụt khoảng 78.000 nhân lực CNTT mỗi năm và đến năm 2020 sẽ thiếu hơn 500.000 nhân lực CNTT.</p>\n\n<p>Dự báo trong 2 năm 2017 và 2018, các cơ sở đào tạo trong cả nước sẽ cho \"ra lò\" khoảng 80.000 nhân lực CNTT, so với nhu cầu tính đến cuối năm 2018, Việt Nam vẫn còn thiếu khoảng 70.000 nhân lực cho lĩnh vực này.</p>\n\n<p class=\"fit-source\">(Theo Người Lao Động)</p>','Khan hiếm nhân lực công nghệ thông tin','','publish','open','open','','khan-hiem-nhan-luc-cong-nghe-thong-tin','','','2018-06-24 08:30:00','2018-06-24 01:30:00','',0,'http://wordpress.local/?p=10',0,'post','',0),(11,1,'2018-08-03 09:00:00','2018-08-03 02:00:00','<p class=\"fit-lead\">Trong bối cảnh kỷ nguyên số và sự bùng nổ của điện toán đám mây cùng Internet vạn vật (IoT), ngành Truyền thông và Mạng máy tính đang trở thành một trong những ngành học then chốt thu hút đông đảo sinh viên.</p>\n\n<p>Ngành Truyền thông và Mạng máy tính trang bị cho sinh viên kiến thức chuyên sâu về thiết kế, xây dựng và quản trị hạ tầng mạng doanh nghiệp, an toàn thông tin mạng và các giải pháp viễn thông hiện đại. Sinh viên tốt nghiệp có thể đảm nhận các vị trí kỹ sư mạng, chuyên viên an ninh mạng, kỹ sư quản trị hệ thống cloud hoặc chuyên viên tư vấn giải pháp mạng.</p>\n\n<p>Theo thống kê việc làm, 100% sinh viên chuyên ngành sau khi tốt nghiệp tại khoa đều có việc làm đúng chuyên ngành với mức thu nhập hấp dẫn tại các nhà mạng viễn thông, tập đoàn công nghệ và ngân hàng lớn.</p>\n\n<p class=\"fit-source\">(Theo Ban Tuyển sinh FIT-TDC)</p>','Truyền thông và Mạng máy tính - Ngành học giàu tiềm năng','','publish','open','open','','truyen-thong-va-mang-may-tinh-nganh-hoc-giau-tiem-nang','','','2018-08-03 09:00:00','2018-08-03 02:00:00','',0,'http://wordpress.local/?p=11',0,'post','',0),(12,1,'2017-10-27 09:00:00','2017-10-27 02:00:00','<p class=\"fit-lead\">Công nghệ ảo hóa (Virtualization) đang là nền tảng cốt lõi của hạ tầng điện toán đám mây hiện đại, giúp tối ưu hóa tài nguyên phần cứng và nâng cao tính bảo mật trong hệ thống thông tin.</p>\n\n<p>Việc ứng dụng các giải pháp ảo hóa như VMware vSphere, Microsoft Hyper-V hay Docker Container cho phép doanh nghiệp vận hành đồng thời nhiều hệ điều hành và dịch vụ trên một máy chủ vật lý duy nhất, tiết kiệm chi phí đầu tư ban đầu và giảm thiểu tối đa thời gian downtime khi có sự cố.</p>\n\n<p>Bài viết chia sẻ một số thủ thuật tối ưu hóa máy ảo: thiết lập RAM động (Dynamic Memory), tối ưu hóa I/O đĩa cứng bằng SSD NVMe, và cấu hình mạng nội bộ ảo (vSwitch) để đạt hiệu năng xử lý cao nhất trong môi trường lab học tập cũng như sản xuất thực tế.</p>\n\n<p class=\"fit-source\">(Theo Bộ môn Hệ thống Thông tin - TDC)</p>','Ứng dụng ảo hóa và thủ thuật máy ảo','','publish','open','open','','ung-dung-ao-hoa-va-thu-thuat-may-ao','','','2017-10-27 09:00:00','2017-10-27 02:00:00','',0,'http://wordpress.local/?p=12',0,'post','',0),(13,1,'2021-10-20 09:00:00','2021-10-20 02:00:00','<p class=\"fit-lead\">Khoa Công nghệ Thông tin phối hợp cùng Hiệp hội Phần mềm và Dịch vụ CNTT Việt Nam (VINASA) tổ chức Hội thảo Chuyên đề \"Chuyển đổi số và Ứng dụng Trí tuệ Nhân tạo trong Doanh nghiệp hiện đại\".</p>\n\n<p>Hội thảo quy tụ các diễn giả là chuyên gia hàng đầu về AI, Machine Learning và Data Science đến từ các doanh nghiệp công nghệ lớn. Sự kiện nhằm cung cấp cái nhìn toàn diện về xu hướng chuyển đổi số tại Việt Nam, các mô hình ngôn ngữ lớn (LLMs), tự động hóa quy trình nghiệp vụ bằng AI và cơ hội việc làm rộng mở cho kỹ sư AI trong tương lai.</p>\n\n<p>Bên cạnh các bài tham luận chuyên môn sâu sắc, sinh viên tham dự còn được trực tiếp trải nghiệm các demo sản phẩm ứng dụng trí tuệ nhân tạo như nhận diện khuôn mặt thời gian thực, trợ lý ảo thông minh và hệ thống phân tích dữ liệu tự động.</p>\n\n<p>Hội thảo diễn ra vào lúc 8h30 ngày 28/10 tại Hội trường lớn nhà H, Trường Cao đẳng Công nghệ Thủ Đức. Toàn thể sinh viên và giảng viên quan tâm đều có thể đăng ký tham gia miễn phí.</p>\n\n<p class=\"fit-source\">(Nguồn: Khoa Công nghệ Thông tin – TDC)</p>','Hội thảo Chuyển đổi số và Ứng dụng Trí tuệ Nhân tạo (AI) trong Doanh nghiệp','','publish','open','open','','hoi-thao-chuyen-doi-so-va-ung-dung-tri-tue-nhan-tao-ai-trong-doanh-nghiep','','','2021-10-20 09:00:00','2021-10-20 02:00:00','',0,'http://wordpress.local/?p=13',0,'post','',0),(14,1,'2021-10-25 08:30:00','2021-10-25 01:30:00','<p class=\"fit-lead\">Ngày hội Việc làm và Kết nối Doanh nghiệp (IT Job Fair) là sự kiện thường niên lớn nhất trong năm do Khoa Công nghệ Thông tin - TDC tổ chức nhằm kết nối sinh viên với các nhà tuyển dụng hàng đầu.</p>\n\n<p>Năm nay, ngày hội thu hút hơn 30 doanh nghiệp hoạt động trong lĩnh vực CNTT, phần mềm, thương mại điện tử và viễn thông với hơn 500 vị trí tuyển dụng thực tập sinh, lập trình viên Junior, chuyên viên kiểm thử phần mềm (Tester) và kỹ sư hạ tầng mạng. Đây là dịp để các bạn sinh viên chuẩn bị tốt nghiệp tìm kiếm việc làm chính thức ngay khi còn ngồi trên ghế nhà trường.</p>\n\n<p>Tại ngày hội, sinh viên được tham gia các buổi phỏng vấn trực tiếp tại gian hàng, nghe tư vấn chỉnh sửa CV chuyên nghiệp từ các chuyên gia nhân sự và tham dự talkshow \"Bí quyết chinh phục nhà tuyển dụng ngành CNTT\".</p>\n\n<p>Chương trình sẽ chính thức khai mạc vào lúc 8h00 ngày 05/11 tại sảnh A trường Cao đẳng Công nghệ Thủ Đức. Sinh viên lưu ý mang theo nhiều bản CV in sẵn và trang phục chỉnh tề khi tham gia phỏng vấn.</p>\n\n<p class=\"fit-source\">(Nguồn: Ban Hợp tác Doanh nghiệp – FIT TDC)</p>','Ngày hội Tuyển dụng và Kết nối Doanh nghiệp IT Job Fair 2021','','publish','open','open','','ngay-hoi-tuyen-dung-va-ket-noi-doanh-nghiep-it-job-fair-2021','','','2021-10-25 08:30:00','2021-10-25 01:30:00','',0,'http://wordpress.local/?p=14',0,'post','',0),(15,1,'2021-11-05 15:00:00','2021-11-05 08:00:00','<p class=\"fit-lead\">Đội tuyển Olympic Tin học của Khoa Công nghệ Thông tin - TDC đã xuất sắc giành được nhiều giải thưởng cao quý tại Kỳ thi Olympic Tin học Sinh viên Toàn quốc năm 2021.</p>\n\n<p>Vượt qua hàng trăm thí sinh tài năng đến từ các trường đại học, cao đẳng trên cả nước, các thành viên đội tuyển FIT-TDC đã thể hiện xuất sắc bản lĩnh, tư duy thuật toán sắc bén và kỹ năng lập trình thi đấu ở bảng thi Khối Cao đẳng và Lập trình Đối kháng (Procon). Thành tích này tiếp tục khẳng định chất lượng đào tạo vững chắc của nhà trường.</p>\n\n<p>Để đạt được kết quả này, thầy và trò đội tuyển đã miệt mài ôn luyện trong suốt 6 tháng với cường độ cao, giải hàng trăm bài tập thuật toán phức tạp trên các nền tảng Codeforces, LeetCode và VNOI dưới sự hướng dẫn tận tâm của các giảng viên bộ môn.</p>\n\n<p>Khoa Công nghệ Thông tin xin gửi lời chúc mừng nồng nhiệt đến các bạn sinh viên và ban huấn luyện. Thành công của đội tuyển là niềm tự hào và nguồn cảm hứng to lớn cho các thế hệ sinh viên tiếp theo nỗ lực rèn luyện, chinh phục đỉnh cao tri thức.</p>\n\n<p class=\"fit-source\">(Nguồn: Ban Giảng viên Chuyên môn – FIT TDC)</p>','Sinh viên FIT-TDC xuất sắc đạt giải cao tại Cuộc thi Olympic Tin học Toàn quốc','','publish','open','open','','sinh-vien-fit-tdc-xuat-sac-dat-giai-cao-tai-cuoc-thi-olympic-tin-hoc-toan-quoc','','','2021-11-05 15:00:00','2021-11-05 08:00:00','',0,'http://wordpress.local/?p=15',0,'post','',0),(16,1,'2021-11-12 10:00:00','2021-11-12 03:00:00','<p class=\"fit-lead\">Trường Cao đẳng Công nghệ Thủ Đức cùng Khoa Công nghệ Thông tin đã chính thức ký kết biên bản ghi nhớ hợp tác toàn diện (MOU) với Công ty Cổ phần Phần mềm FPT (FPT Software).</p>\n\n<p>Thỏa thuận hợp tác mở ra nhiều cơ hội thiết thực cho sinh viên khoa CNTT, bao gồm các chương trình đào tạo kỹ năng thực chiến theo chuẩn doanh nghiệp, học bổng tài trợ tài năng trẻ, chương trình tham quan doanh nghiệp (Company Tour) và ưu tiên tiếp nhận sinh viên thực tập có hưởng lương tại các trung tâm phần mềm của FPT.</p>\n\n<p>Đại diện FPT Software đánh giá cao chất lượng đào tạo thực hành của sinh viên TDC, đặc biệt là tính kỷ luật, sự chủ động và khả năng thích nghi nhanh với công nghệ mới. Doanh nghiệp cam kết sẽ đồng hành chặt chẽ cùng nhà trường trong việc cập nhật giáo trình và hỗ trợ giảng viên tham gia các dự án công nghệ thực tế.</p>\n\n<p>Lễ ký kết đánh dấu một cột mốc quan trọng trong chiến lược gắn kết đào tạo với nhu cầu doanh nghiệp của nhà trường, góp phần nâng cao tỷ lệ sinh viên có việc làm chất lượng cao ngay sau khi tốt nghiệp.</p>\n\n<p class=\"fit-source\">(Nguồn: Phòng Truyền thông và Hợp tác Doanh nghiệp – TDC)</p>','Lễ ký kết Thỏa thuận Hợp tác Đào tạo và Tiếp nhận Thực tập sinh cùng FPT Software','','publish','open','open','','le-ky-ket-thoa-thuan-hop-tac-dao-tao-va-tiep-nhan-thuc-tap-sinh-cung-fpt-software','','','2021-11-12 10:00:00','2021-11-12 03:00:00','',0,'http://wordpress.local/?p=16',0,'post','',0);
